    // recognized members are not guessed out of the cluster and therefore do
    // not suppress anything.
    assert_data_eq!(
        complete!(command(), "-fx [TAB]"),
        snapbox::str![[r#"
--fast
--safe
--tag
--help	Print help
"#]],
    );
    assert_data_eq!(
        complete!(command(), "-xt v1 [TAB]"),
        snapbox::str![[r#"
--fast
--safe
--tag
--help	Print help
"#]],
    );

