use clap::Command;

fn tool_command() -> Command {
    Command::new("tool")
        .infer_subcommands(true)
        .arg(clap::Arg::new("target").value_parser(["local", "remote"]))
        .subcommand(
            Command::new("run")
                .visible_alias("r")
                .arg(clap::Arg::new("profile").long("profile"))
                .arg(clap::Arg::new("run_target").value_parser(["local", "remote"])),
        )
        .subcommand(
            Command::new("remote")
                .visible_alias("rem")
                .arg(clap::Arg::new("url").long("url")),
        )
        .subcommand(Command::new("reset"))
        .subcommand(Command::new("secret").hide(true))
}

fn complete(input: &str) -> String {
    let mut cmd = tool_command();
    let mut args = vec![std::ffi::OsString::from("tool")];
    let arg_index;
    args.extend(input.split_whitespace().map(std::ffi::OsString::from));
    if input.ends_with(char::is_whitespace) {
        args.push(std::ffi::OsString::default());
    }
    arg_index = args.len() - 1;
    match clap_complete::engine::complete(&mut cmd, args, arg_index, None) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| {
                if let Some(h) = c.get_help() {
                    format!("{}\t{}", c.get_value().to_str().unwrap(), h)
                } else {
                    c.get_value().to_str().unwrap().to_owned()
                }
            })
            .collect::<Vec<_>>()
            .join("\n"),
        Err(e) => format!("ERR: {e}"),
    }
}

