    // Canonical vs alias vs full-word repeated calls on the SAME command must
    // yield equivalent results without leftover inferred state.
    let mut cmd = tool_command();
    let a = complete_on(&mut cmd, "run ");
    let b = complete_on(&mut cmd, "r ");
    let c = complete_on(&mut cmd, "ru ");
    let d = complete_on(&mut cmd, "run ");
    println!("run: {a:?}\nr:   {b:?}\nru:  {c:?}\nrun2:{d:?}");
    assert_eq!(a, b);
    assert_eq!(b, c);
    assert_eq!(c, d);
}

fn complete_on(cmd: &mut Command, input: &str) -> String {
    let mut args = vec![std::ffi::OsString::from("tool")];
    args.extend(input.split_whitespace().map(std::ffi::OsString::from));
    if input.ends_with(char::is_whitespace) {
        args.push(std::ffi::OsString::default());
    }
    let arg_index = args.len() - 1;
    match clap_complete::engine::complete(cmd, args, arg_index, None) {
        Ok(cs) => cs
            .into_iter()
            .map(|c| c.get_value().to_str().unwrap().to_owned())
            .collect::<Vec<_>>()
            .join("\n"),
        Err(e) => format!("ERR: {e}"),
    }
}

